WITH valid AS (SELECT *, SUBSTRING(dept_name, 1, 2) dept_name_prefix FROM departments WHERE dept_name IS NOT NULL AND dept_name = 'Marketing') SELECT location, COUNT(CASE WHEN location = 'Bangkok' THEN 1 END) AS bangkok_count, ROUND(SUM(budget) / NULLIF(COUNT(CASE WHEN dept_name = 'HR' THEN 1 END), 0), 2) AS budget_per_hr, SORT_ARRAY(COLLECT_SET(location)) AS location_list, ROUND(AVG(budget), 2) AS avg_budget, APPROX_PERCENTILE(budget, ARRAY(0.25, 0.5, 0.75)) AS budget_quartiles FROM valid GROUP BY ROLLUP (location) ORDER BY bangkok_count DESC NULLS FIRST
